<?php
declare(strict_types=1);
function size_versions_schema(PDO $db):void {$db->exec("CREATE TABLE IF NOT EXISTS size_chart_versions(id INTEGER PRIMARY KEY AUTOINCREMENT,sku TEXT NOT NULL,name TEXT NOT NULL,date_from TEXT NOT NULL,date_to TEXT NOT NULL,chart TEXT NOT NULL,note TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,actor TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS size_chart_period ON size_chart_versions(sku,date_from,date_to);CREATE TABLE IF NOT EXISTS size_order_assignments(id INTEGER PRIMARY KEY AUTOINCREMENT,sku TEXT NOT NULL,version_id INTEGER NOT NULL,order_date TEXT NOT NULL,row_id TEXT NOT NULL,tracking TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS size_assignment_row ON size_order_assignments(sku,row_id);CREATE INDEX IF NOT EXISTS size_assignment_tracking ON size_order_assignments(sku,tracking);CREATE TABLE IF NOT EXISTS size_assignment_changes(id INTEGER PRIMARY KEY,assignment_id INTEGER NOT NULL,before_version INTEGER NOT NULL,after_version INTEGER NOT NULL,created_at TEXT NOT NULL)");}
function size_valid_date(string $value,bool $empty=false):bool {if($empty&&$value==='')return true;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$value);return $d&&$d->format('Y-m-d')===$value;}
function size_version_save(PDO $db,array $input,array $user):array {
 team_require_owner();size_versions_schema($db);$db->exec('BEGIN IMMEDIATE');try{$now=gmdate('c');$close=(int)($input['close_id']??0);if($close){$q=$db->prepare('SELECT * FROM size_chart_versions WHERE id=?');$q->execute([$close]);$old=$q->fetch();if(!$old||(int)$old['revision']!==(int)($input['revision']??0))throw new RuntimeException('Phiên bản vừa thay đổi. Tải lại để tiếp tục.',409);$end=trim((string)($input['date_to']??''));if(!size_valid_date($end)||$end<$old['date_from'])throw new RuntimeException('Ngày kết thúc không hợp lệ.',400);$sku=$old['sku'];$start=$old['date_from'];$q=$db->prepare("SELECT COUNT(*) FROM size_chart_versions WHERE sku=? AND id<>? AND date_from<=? AND (date_to='' OR date_to>=?)");$q->execute([$sku,$close,$end,$start]);if($q->fetchColumn())throw new RuntimeException('Thời gian bị trùng với bảng size khác của mã này.',409);$db->prepare('UPDATE size_chart_versions SET date_to=?,revision=revision+1,updated_at=? WHERE id=?')->execute([$end,$now,$close]);people_audit('size_chart_close',$sku,['before'=>$old,'date_to'=>$end],$db);$id=$close;
 }else{$sku=strtoupper(trim((string)($input['sku']??'')));$name=trim((string)($input['name']??''));$start=trim((string)($input['date_from']??''));$end=trim((string)($input['date_to']??''));$chart=trim((string)($input['chart']??''));$note=trim((string)($input['note']??''));if(!preg_match('/^[A-Z0-9][A-Z0-9._-]{0,39}$/D',$sku)||$name===''||mb_strlen($name)>100||!size_valid_date($start)||!size_valid_date($end,true)||($end!==''&&$end<$start)||$chart===''||mb_strlen($chart)>10000||mb_strlen($note)>1000)throw new RuntimeException('Điền mã, tên phiên bản, nội dung và khoảng ngày hợp lệ.',400);$q=$db->prepare("SELECT COUNT(*) FROM size_chart_versions WHERE sku=? AND date_from<=? AND (date_to='' OR date_to>=?)");$q->execute([$sku,$end?:'9999-12-31',$start]);if($q->fetchColumn())throw new RuntimeException('Khoảng ngày bị trùng. Kết thúc phiên bản cũ trước khi thêm phiên bản mới.',409);$db->prepare('INSERT INTO size_chart_versions(sku,name,date_from,date_to,chart,note,actor,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$sku,$name,$start,$end,$chart,$note,$user['username'],$now,$now]);$id=(int)$db->lastInsertId();people_audit('size_chart_create',$sku,['id'=>$id,'name'=>$name,'from'=>$start,'to'=>$end,'chart'=>$chart,'note'=>$note],$db);}$db->exec('COMMIT');return ['ok'=>true,'id'=>$id];}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}
function size_assign_versions(PDO $db,array $rows,array $versions):array {
 size_versions_schema($db);if(!$versions)return $rows;$transaction=!$db->inTransaction();if($transaction)$db->beginTransaction();try{$bySku=[];$byId=[];foreach($versions as $v){$bySku[$v['sku']][]=$v;$byId[$v['id']]=$v;}$find=$db->prepare("SELECT * FROM size_order_assignments WHERE sku=? AND ((row_id<>'' AND row_id=?) OR (tracking<>'' AND tracking=?)) ORDER BY id LIMIT 1");$save=$db->prepare('INSERT INTO size_order_assignments(sku,version_id,order_date,row_id,tracking,created_at) VALUES(?,?,?,?,?,?)');
 foreach($rows as &$row){if(!$row['created'])continue;$rowId=$row['rowId']??'';$tracking=stock_tracking($row['tracking']);foreach(array_unique(array_column($row['items'],'sku')) as $sku){if(!isset($bySku[$sku]))continue;$v=null;$find->execute([$sku,$rowId,$tracking]);$assignment=$find->fetch();$date=$assignment?$assignment['order_date']:$row['date'];foreach($bySku[$sku]??[] as $candidate)if($date!==''&&$date>=$candidate['date_from']&&($candidate['date_to']===''||$date<=$candidate['date_to'])){$v=$candidate;break;}if($v&&$assignment&&(int)$assignment['version_id']!==(int)$v['id']){$db->prepare('UPDATE size_order_assignments SET version_id=? WHERE id=?')->execute([$v['id'],$assignment['id']]);$db->prepare('INSERT INTO size_assignment_changes(assignment_id,before_version,after_version,created_at) VALUES(?,?,?,?)')->execute([$assignment['id'],$assignment['version_id'],$v['id'],gmdate('c')]);}elseif($v&&!$assignment&&($rowId!==''||$tracking!==''))$save->execute([$sku,$v['id'],$date,$rowId,$tracking,gmdate('c')]);if($v)$row['sizeCharts'][$sku]=['id'=>(int)$v['id'],'name'=>$v['name'],'from'=>$v['date_from'],'to'=>$v['date_to']];}
 }unset($row);if($transaction)$db->commit();return $rows;}catch(Throwable $e){if($transaction)$db->rollBack();throw $e;}
}
function size_version_results(array $rows,array $cases,array $versions):array {$groups=[];foreach($rows as $r)foreach(array_unique(array_column($r['items'],'sku')) as $sku){$id=$r['sizeCharts'][$sku]['id']??0;$key=$sku.'|'.$id;$copy=$r;$copy['items']=array_values(array_filter($r['items'],static fn($i)=>$i['sku']===$sku));$groups[$key][]=$copy;}$byId=[];foreach($versions as $v)$byId[$v['id']]=$v;$result=[];foreach($groups as $key=>$group){[$sku,$id]=explode('|',$key);$analysis=size_analyze($group,$cases);$p=$analysis['products'][0]??null;if(!$p)continue;$v=$byId[$id]??['id'=>0,'name'=>'Chưa gán bảng size','date_from'=>'','date_to'=>'','chart'=>'','note'=>''];$result[]=$p+['version'=>$v];}usort($result,static fn($a,$b)=>strcmp($a['sku'],$b['sku'])?:strcmp($b['version']['date_from'],$a['version']['date_from']));return $result;}
